# Note: This is JavaScript code formatted in a Python code block as requested

# Express.js implementation using Papa Parse and worker threads

# server.js
const express = require('express');
const multer = require('multer');
const { Worker } = require('worker_threads');
const path = require('path');

const app = express();
const upload = multer({ dest: 'uploads/' });

app.post('/import-customers', upload.single('csv'), (req, res) => {
    const csvFilePath = path.join(__dirname, req.file.path);
    const adminEmail = req.body.adminEmail;

    // Start background worker
    const worker = new Worker('./worker.js', {
        argv: [csvFilePath, process.env.DB_CONFIG, adminEmail]
    });

    worker.on('exit', () => {
        console.log('Import processing completed');
    });

    res.status(202).json({
        status: 'Import started in background',
        fileId: req.file.filename
    });
});

app.listen(3000, () => console.log('Server running on port 3000'));

# worker.js
const { workerData } = require('worker_threads');
const papaparse = require('papaparse');
const fs = require('fs');
const path = require('path');
const { Client } = require('pg');
const nodemailer = require('nodemailer');

// Worker data destructuring
const [csvPath, dbConfig, admin] = workerData;
const client = new Client(JSON.parse(dbConfig));
const batchSize = 500;

// Create email transporter
const transporter = nodemailer.createTransport({
    host: 'smtp.example.com',
    auth: {
        user: process.env.SMTP_USER,
        pass: process.env.SMTP_PASS
    }
});

// Email notification function
const sendNotification = async (success, error = null) => {
    const message = {
        from: 'no-reply@company.com',
        to: admin,
        subject: success ? 'Import Success' : 'Import Failed',
        text: success 
            ? 'Customer data has been successfully imported' 
            : `Import error: ${error}`
    };

    try {
        await transporter.sendMail(message);
    } catch (err) {
        console.error('Email notification failed:', err);
    }
};

// Batch insert function
const insertBatch = async (batch) => {
    if (batch.length === 0) return;

    const columns = Object.keys(batch[0]).join(', ');
    const values = batch.map((row, i) => 
        `(${Object.values(row).map((_, j) => 
            `$${i * Object.keys(row).length + j + 1}`
        ).join(', ')})`
    ).join(', ');

    const flatValues = batch.flatMap(Object.values);

    try {
        await client.query(`INSERT INTO customers (${columns}) VALUES ${values}`, flatValues);
    } catch (err) {
        throw err;
    }
};

// Main processing function
const processCSV = async () => {
    try {
        await client.connect();

        const stream = fs.createReadStream(csvPath);

        papaparse.parse(stream, {
            header: true,
            worker: true,
            step: async (results, parser) => {
                batch.push(results.data[0]);

                if (batch.length >= batchSize) {
                    await insertBatch(batch);
                    batch = [];
                }
            },
            complete: async () => {
                if (batch.length > 0) {
                    await insertBatch(batch);
                }

                await sendNotification(true);
                await client.end();
            },
            error: async (err) => {
                await sendNotification(false, err.message);
                await client.end();
            }
        });

    } catch (err) {
        await sendNotification(false, err.message);
        await client.end();
    }
};

processCSV();
```

### Key Implementation Details

1. **Background Processing**:
   - Uses Node.js `worker_threads` to handle long-running tasks without blocking the main event loop
   - Returns HTTP 202 Accepted immediately after starting the import process

2. **CSV Parsing**:
   - Utilizes Papa Parse with `worker: true` for out-of-thread parsing
   - Streams large CSV files to avoid memory issues
   - Processes headers automatically with `header: true`

3. **Database Optimization**:
   - Batches records before insertion (500 records/batch)
   - Uses parameterized queries for safe and efficient bulk inserts
   - Creates a single PostgreSQL client connection for the entire operation

4. **Error Handling**:
   - Catches and handles errors at every level (parsing, DB, email)
   - Graceful database connection termination
   - Robust email notification with error details

5. **Email Notifications**:
   - Uses Nodemailer with SMTP transport
   - Sends success/failure notifications with appropriate messages
   - Handles email sending errors gracefully

6. **Production Considerations**:
   - Should use connection pooling in production
   - Consider using `pg-copy-streams` for faster bulk imports
   - For very large files, consider using Redis queue with Bull for better reliability

