                String[] orderingOptions = {"name", "price", "-price", "description"};
                currentOrdering = orderingOptions[position];
                if (searchQuery.isEmpty()) {
                    loadPhotos(currentOrdering);
                } else {
                    searchPhotos(searchQuery, currentOrdering);
                }
            }

            @Override
            public void onNothingSelected(AdapterView<?> parent) {}
        });
    }

    private void loadPhotos(String ordering) {
        Call<List<Photo>> call = photoApiService.getPhotos(ordering);
        call.enqueue(new Callback<List<Photo>>() {
            @Override
            public void onResponse(Call<List<Photo>> call, Response<List<Photo>> response) {
                if (response.isSuccessful()) {
                    photoList = response.body();
                    photoAdapter.updatePhotos(photoList);
                }
            }

            @Override
            public void onFailure(Call<List<Photo>> call, Throwable t) {
                Toast.makeText(MainActivity.this, "Failed to load photos", Toast.LENGTH_SHORT).show();
            }
        });
    }

    private void searchPhotos(String query, String ordering) {
        Call<List<Photo>> call = photoApiService.searchPhotos(query, ordering);
        call.enqueue(new Callback<List<Photo>>() {
            @Override
            public void onResponse(Call<List<Photo>> call, Response<List<Photo>> response) {
                if (response.isSuccessful()) {
                    photoList = response.body();
                    photoAdapter.updatePhotos(photoList);
                }
            }

            @Override
            public void onFailure(Call<List<Photo>> call, Throwable t) {
                Toast.makeText(MainActivity.this, "Search failed", Toast.LENGTH_SHORT).show();
            }
        });
    }
