                    'Dhuhr': times['Dhuhr'],
                    'Asr': times['Asr'],
                    'Maghrib': times['Maghrib'],
                    'Isha': times['Isha']
                }
            else:
                # Skip if coordinates are missing
                continue

        current_date += delta

    return prayer_data

