I'll explain how the app displays photo comparisons and provide detailed information on building the Android app with UI/UX considerations and backend integration.

### Comparison Functionality

The backend already returns photos sorted by name, price, and description in ascending order. This is implemented in the PhotoViewSet:

```python
# views.py
queryset = Photo.objects.filter(approved=True).order_by('name', 'price', 'description')
```

This means when the app fetches photos from the API, they're already sorted for comparison. For additional sorting options, we've added the OrderingFilter:

```python
# views.py
filter_backends = [filters.SearchFilter, DjangoFilterBackend, filters.OrderingFilter]
ordering_fields = ['name', 'price', 'description']
ordering = ['name', 'price', 'description']
```

### Android App Implementation

#### 1. Photo Model
```java
public class Photo {
    private int id;
    private String name;
    private double price;
    private String description;
    private String imageUrl;
    private boolean approved;
    private String submittedAt;

    // Getters and setters
}
```

#### 2. Retrofit API Service
```java
public interface PhotoApiService {
    @GET("photos/")
    Call<List<Photo>> getPhotos(@Query("ordering") String ordering);

    @GET("photos/")
    Call<List<Photo>> searchPhotos(@Query("search") String query, @Query("ordering") String ordering);

    @Multipart
    @POST("photos/")
    Call<Photo> uploadPhoto(
        @Part("name") RequestBody name,
        @Part("price") RequestBody price,
        @Part("description") RequestBody description,
        @Part MultipartBody.Part image
    );
}
```

#### 3. Main Activity with RecyclerView
```java
public class MainActivity extends AppCompatActivity {
    private RecyclerView recyclerView;
    private PhotoAdapter photoAdapter;
    private List<Photo> photoList;
    private PhotoApiService photoApiService;
    private String currentOrdering = "name";

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        setupViews();
        setupSearch();
        setupSorting();
        loadPhotos(currentOrdering);
    }

    private void setupViews() {
        recyclerView = findViewById(R.id.recyclerView);
        recyclerView.setLayoutManager(new LinearLayoutManager(this));
        photoAdapter = new PhotoAdapter(new ArrayList<>());
        recyclerView.setAdapter(photoAdapter);

        photoApiService = PhotoApiClient.getApiService();
    }

    private void setupSearch() {
        SearchView searchView = findViewById(R.id.searchView);
        searchView.setOnQueryTextListener(new SearchView.OnQueryTextListener() {
            @Override
            public boolean onQueryTextSubmit(String query) {
                searchPhotos(query, currentOrdering);
                return true;
            }

            @Override
            public boolean onQueryTextChange(String newText) {
                return false;
            }
        });
    }

    private void setupSorting() {
        Spinner sortSpinner = findViewById(R.id.sortSpinner);
        ArrayAdapter<CharSequence> adapter = ArrayAdapter.createFromResource(this,
                R.array.sort_options, android.R.layout.simple_spinner_item);
        adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
        sortSpinner.setAdapter(adapter);

        sortSpinner.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener() {
            @Override
            public void onItemSelected(AdapterView<?> parent, View view, int position, long id) {
                String[] orderingOptions = {"name", "price", "-price", "description"};
                currentOrdering = orderingOptions[position];
                if (searchQuery.isEmpty()) {
                    loadPhotos(currentOrdering);
                } else {
                    searchPhotos(searchQuery, currentOrdering);
                }
            }

            @Override
            public void onNothingSelected(AdapterView<?> parent) {}
        });
    }

    private void loadPhotos(String ordering) {
        Call<List<Photo>> call = photoApiService.getPhotos(ordering);
        call.enqueue(new Callback<List<Photo>>() {
            @Override
            public void onResponse(Call<List<Photo>> call, Response<List<Photo>> response) {
                if (response.isSuccessful()) {
                    photoList = response.body();
                    photoAdapter.updatePhotos(photoList);
                }
            }

            @Override
            public void onFailure(Call<List<Photo>> call, Throwable t) {
                Toast.makeText(MainActivity.this, "Failed to load photos", Toast.LENGTH_SHORT).show();
            }
        });
    }

    private void searchPhotos(String query, String ordering) {
        Call<List<Photo>> call = photoApiService.searchPhotos(query, ordering);
        call.enqueue(new Callback<List<Photo>>() {
            @Override
            public void onResponse(Call<List<Photo>> call, Response<List<Photo>> response) {
                if (response.isSuccessful()) {
                    photoList = response.body();
                    photoAdapter.updatePhotos(photoList);
                }
            }

            @Override
            public void onFailure(Call<List<Photo>> call, Throwable t) {
                Toast.makeText(MainActivity.this, "Search failed", Toast.LENGTH_SHORT).show();
            }
        });
    }
}
```

#### 4. Photo Adapter
```java
public class PhotoAdapter extends RecyclerView.Adapter<PhotoAdapter.PhotoViewHolder> {
    private List<Photo> photos;

    public PhotoAdapter(List<Photo> photos) {
        this.photos = photos;
    }

    @NonNull
    @Override
    public PhotoViewHolder onCreateViewHolder(@NonNull ViewGroup parent, int viewType) {
        View view = LayoutInflater.from(parent.getContext()).inflate(R.layout.photo_item, parent, false);
        return new PhotoViewHolder(view);
    }

    @Override
    public void onBindViewHolder(@NonNull PhotoViewHolder holder, int position) {
        Photo photo = photos.get(position);
        holder.bind(photo);
    }

    @Override
    public int getItemCount() {
        return photos.size();
    }

    public void updatePhotos(List<Photo> newPhotos) {
        photos.clear();
        photos.addAll(newPhotos);
        notifyDataSetChanged();
    }

    static class PhotoViewHolder extends RecyclerView.ViewHolder {
