        System.out.println("------------------------------------------------------");
        System.out.println("output | 110 | 101 | 001 | 000 | 011 | 010 | 111 | 100\n");
        System.out.println("In terms of hexadecimal notation, the S-box is given by: ");
        System.out.println("input  | 0 | 1 | 2 | 3 | 4 | 5 | 6 | 7");
        System.out.println("--------------------------------------");
        System.out.println("output | 6 | 5 | 1 | 0 | 3 | 2 | 7 | 4");

        // Compute LAT and normalize it (NLAT)
        int[][] nlatTable = new int[8][8];

        for (int a = 0; a < 8; a++) {
            for (int b = 0; b < 8; b++) {
                int latValue = lat(inputVectors, outputVectors, a, b);
                nlatTable[a][b] = latValue - 4;  // Normalize
            }
        }

        try {
            validateNLAT(nlatTable, expectedOutput);
            System.out.println("✅ All entries match the expected output.");
        } catch (ValidationException e) {
            System.err.println("❌ Validation failed: " + e.getMessage());
            System.exit(1);  // Terminate on validation failure
        }

        // Print NLAT if validation passes
        System.out.println("\nNormalized Linear Approximation Table:");
        for (int[] row : nlatTable) {
            for (int val : row) {
                System.out.print(val + "\t");
            }
            System.out.println();
        }
    }

    /**
     * Compute the Linear Approximation Table (LAT) entry for mask pair (a, b)
     */
    public static int lat(int[][] input, int[][] output, int a, int b) {
        int count = 0;

        for (int x = 0; x < 8; x++) {
            // Compute input parity (a_parity)
            int aParity = 0;
            for (int i = 0; i < 3; i++) {
                if ((a >> (2 - i) & 1) == 1) {
                    aParity ^= input[x][i];
                }
            }

            // Compute output parity (b_parity)
            int bParity = 0;
            for (int j = 0; j < 3; j++) {
                if ((b >> (2 - j) & 1) == 1) {
                    bParity ^= output[x][j];
                }
            }

            if (aParity == bParity) {
                count++;
            }
        }
        return count;
    }

    /**
     * Validate computed NLAT against expected values
     * @throws ValidationException on first mismatch
     */
    private static void validateNLAT(int[][] computed, int[][] expected) throws ValidationException {
        for (int a = 0; a < 8; a++) {
            for (int b = 0; b < 8; b++) {
                if (computed[a][b] != expected[a][b]) {
                    throw new ValidationException(
                        String.format("Mismatch at a=%d, b=%d: computed %d, expected %d",
                                     a, b, computed[a][b], expected[a][b])
                    );
                }
            }
        }
    }

    /**
     * Custom exception for LAT validation failures
     */
    private static class ValidationException extends Exception {
        public ValidationException(String message) {
            super(message);
        }
    }
