class PrayerCalculator:
    def __init__(self, timezone_offset=2):  # Egypt uses EET (UTC+2)
        self.calculator = praytimes.PrayTimes()
        self.calculator.adjust({'timeformat': '24h', 'highlat': 'AngleBased'})
        self.timezone_offset = timezone_offset

    def calculate(self, date, latitude, longitude):
        if latitude is None or longitude is None:
            return None

        self.calculator.set_date(date)
        times = self.calculator.get_times(date, (latitude, longitude), self.timezone_offset)

        # Map praytimes output to standard prayer names
        return {
            'Fajr': times['fajr'],
            'Dhuhr': times['dhuhr'],
            'Asr': times['asr'],
            'Maghrib': times['maghrib'],
            'Isha': times['isha']
        }

