```python
# backend/markdown_validator.py
import mistune  # Markdown parser for validation
from datetime import datetime

class MarkdownValidator:
    def __init__(self):
        self.parser = mistune.Parser()
        self.renderer = mistune.HTMLRenderer()

    def validate_content(self, content: str) -> dict:
        """Validate markdown content and enforce documentation standards"""
        try:
            # Basic markdown validation
            ast = self.parser.parse(content)
            html = self.renderer.render(ast)

            # Enforce documentation standards
            issues = []

            # Rule 1: Must start with H1 heading
            if not content.startswith('# '):
                issues.append("Missing main heading (H1) at start of document")

            # Rule 2: Ensure H2 headings follow H1
            lines = content.split('\n')
            h1_found = False
            for i, line in enumerate(lines):
                if line.startswith('# ') and not h1_found:
                    h1_found = True
                elif h1_found and i > 0 and not line.startswith('## '):
                    issues.append("First heading after H1 must be H2 (## Heading)")
                    break

            # Rule 3: Validate image syntax
            if '!' in content:
                import re
                image_pattern = r'!\[.*?\]\(.*?\)'
                for line in content.split('\n'):
                    if '!' in line and not re.search(image_pattern, line):
                        issues.append("Invalid image syntax detected - use ![alt](url) format")
                        break

            # Rule 4: Minimum content length
            if len(lines) < 15:
                issues.append("Document too short - minimum 15 lines required")

            # Rule 5: Required sections
            required_sections = ['## Introduction', '## Usage', '## Examples']
            for section in required_sections:
                if section not in content:
                    issues.append(f"Missing required section: {section}")

            return {
                'valid': len(issues) == 0,
                'html_preview': html,
                'issues': issues,
                'word_count': len(content.split()),
                'timestamp': datetime.now().isoformat()
            }
        except Exception as e:
            return {
                'valid': False,
                'error': str(e),
                'issues': ['Invalid markdown syntax']
            }

# Example usage
if __name__ == "__main__":
    validator = MarkdownValidator()
    test_content = """# API Documentation
## Introduction
This is a sample API documentation.

## Usage
How to use the API.

## Examples
Sample code examples."""
    result = validator.validate_content(test_content)
    print("Validation Result:", result)
```

