int mkdir_p(const char *path) {
    char *tmp = strdup(path);
    if (!tmp) return -1;

    char *p = tmp;
    if (*p == '/') p++;

    int status = 0;

    while (*p) {
        while (*p && *p != '/') p++;
        if (*p == '\0') break;
        *p = '\0';

        if (mkdir(tmp, 0777) < 0) {
            if (errno != EEXIST) {
                status = -1;
                break;
            }
        }

        *p = '/';
        p++;
    }

    if (status == 0 && mkdir(tmp, 0777) < 0) {
        if (errno != EEXIST) status = -1;
    }

    free(tmp);
    return status;
}
